function magnitudeSuffix(bucket) {
  if (bucket < 5) return ["", "K", "M", "B", "T"][bucket];
  let n = bucket + 22, s = "";
  while (n) {
    n--;
    s = String.fromCharCode(65 + n % 26) + s;
    n = Math.floor(n / 26);
  }
  return s;
}
